// wf.listing.extract > "Call input"
// Input: the listing's text, jurisdiction and today's date there, and the Text service's answer.
// Output: the wf.llm.call input for P3 (active version unless the caller asks for one).
const s = $('Start').first().json;
const c = $('Context').first().json;
return [{ json: { prompt: 'P3_listing_extractor', version: s.version ?? null, model: s.model || null,
  vars: { message: c.text, jurisdiction: c.jurisdiction_code, today: c.today, default_currency: (c.ctx || {}).default_currency },
  meta: { listing_id: c.listing_id } } }];

// wf.listing.extract > "Check listing"
// Deterministic checks after P3 (spec 9.4, D-076, D-077): plausible rent ranges (lib/listing_check.js),
// main units to minor units with the currency exponent, one currency per listing, and issue codes
// for what the owner must confirm, including what the photos show against the text (P7, lib/photo_check.js).
// The model's answer and the checked fields are both kept in app.listings.extraction; the agent step
// records the call without the listing text.
// Deterministic checks after P3 (spec 9.4 post-validation, D-076). The model gives amounts in main
// units. A rent outside the plausible range for its currency (main units per month; weekly rents
// are compared as 52/12 of a week) is set to null with an issue: this catches scale errors such as
// 1,225,000 dinars for 1,225 (spec 3.1). A deposit is checked against the same range; 0 is
// accepted. Issues added here are codes, never sentences (spec 17.1).
//
// out: the validated P3 output; ranges: {currency: [min, max]} from the setting listing.rent_range;
// fallbackCurrency: the jurisdiction's currency, used when an amount has none; text: the listing text,
// for the date check (optional: without it the date is not checked).
// An availability date is kept only when the text says something about when (a date, a month, a weekday,
// "libre", "dispo", "now", "توا"...): with nothing of the kind the model invented it, usually today (D-083).
// Returns {fields, issues, changed}: fields is a copy of out with the checks applied.
const MONTHS = 'janvier|janv|fevrier|fevr|fev|mars|avril|avr|mai|juin|juillet|juil|aout|septembre|sept|octobre|oct|novembre|nov|decembre|dec|' +
  'january|jan|february|feb|march|mar|april|apr|may|june|jun|july|jul|august|aug|september|sep|october|november|december';
const WHEN_WORDS = 'libre|libres|dispo|dispos|disponible|disponibles|disponibilite|immediat|immediate|immediatement|de suite|tout de suite|' +
  'des maintenant|maintenant|a partir|a compter|rentree|semaine prochaine|mois prochain|debut|mi|fin|lundi|mardi|mercredi|jeudi|vendredi|' +
  'samedi|dimanche|available|availability|from|now|immediately|asap|move in|move-in|next week|next month|monday|tuesday|wednesday|' +
  'thursday|friday|saturday|sunday|tawa|tawwa|taw|mel|men|ba3d|awel|ekher|jenfi|fifri|avril|juan|juillet|out';
const WHEN_RE = new RegExp(`(?<![\\p{L}\\p{N}])(${MONTHS}|${WHEN_WORDS})(?![\\p{L}\\p{N}])`, 'iu');
const DATE_RE = /(?<![\d])\d{1,2}\s*[\/.-]\s*\d{1,2}(\s*[\/.-]\s*\d{2,4})?(?![\d])|(?<![\d])(19|20)\d{2}(?![\d])|(?<![\d])\d{1,2}\s*(er|eme|e|st|nd|rd|th)(?![\p{L}])/iu;
const WHEN_AR = /جانفي|فيفري|مارس|أفريل|افريل|ماي|جوان|جويلية|أوت|اوت|سبتمبر|أكتوبر|اكتوبر|نوفمبر|ديسمبر|يناير|فبراير|أبريل|ابريل|مايو|يونيو|يوليو|أغسطس|اغسطس|متوفر|متوفرة|متاح|متاحة|توا|حالا|فورا|فوري|فورية|مباشرة|ابتداء|ابتداءً|بداية|نهاية|الشهر|الأسبوع|الاسبوع|السبت|الأحد|الاحد|الاثنين|الإثنين|الثلاثاء|الأربعاء|الاربعاء|الخميس|الجمعة/;

function dateMentioned(text) {
  const t = String(text || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  return WHEN_RE.test(t) || DATE_RE.test(t) || WHEN_AR.test(String(text || ''));
}

function checkListing(out, ranges, fallbackCurrency, text) {
  if (!out || typeof out !== 'object') return { fields: out, issues: [], changed: [] };
  const f = JSON.parse(JSON.stringify(out));
  const issues = [];
  const changed = [];
  const R = ranges || {};
  if (f.rent_amount !== null && f.rent_amount !== undefined) {
    if (!f.rent_currency) { f.rent_currency = fallbackCurrency || null; issues.push('rent_currency_assumed'); changed.push('rent_currency'); }
    if (!f.rent_period) { f.rent_period = 'month'; changed.push('rent_period'); }
    if (!f.rent_scope) { f.rent_scope = 'unknown'; changed.push('rent_scope'); }
    const r = R[f.rent_currency];
    const monthly = f.rent_period === 'week' ? (f.rent_amount * 52) / 12 : f.rent_amount;
    if (!r) issues.push('rent_range_unknown');
    else if (monthly < r[0] || monthly > r[1]) {
      issues.push('rent_out_of_range');
      f.rent_amount = null; f.rent_currency = null; f.rent_period = null; f.rent_scope = null;
      changed.push('rent_amount');
    }
  }
  if (f.deposit_amount !== null && f.deposit_amount !== undefined) {
    if (!f.deposit_currency) { f.deposit_currency = f.rent_currency || fallbackCurrency || null; changed.push('deposit_currency'); }
    const r = R[f.deposit_currency];
    if (r && f.deposit_amount !== 0 && (f.deposit_amount < r[0] || f.deposit_amount > r[1])) {
      issues.push('deposit_out_of_range');
      f.deposit_amount = null; f.deposit_currency = null;
      changed.push('deposit_amount');
    }
  }
  if (text !== undefined && f.available_from && !dateMentioned(text)) {
    issues.push('available_from_not_in_text');
    f.available_from = null;
    changed.push('available_from');
  }
  if (Array.isArray(f.amenities)) f.amenities = [...new Set(f.amenities)].sort();
  return { fields: f, issues, changed };
}

// Main units to minor units with the currency exponent (app.currencies), for storage.
function toMinorUnits(amount, currency, exponents) {
  if (amount === null || amount === undefined || !currency || !exponents ||
      !Object.prototype.hasOwnProperty.call(exponents, currency)) return null;
  const n = Number(amount);
  return Number.isFinite(n) && n >= 0 ? Math.round(n * Math.pow(10, Number(exponents[currency]))) : null;
}

if (typeof module !== 'undefined') module.exports = { checkListing, toMinorUnits, dateMentioned };

// Deterministic checks after P7 (spec 11.2, D-081), shared by wf.intake.photos, wf.listing.extract and the
// evaluation. The model describes one photo; the code tidies the answer, raises review flags, drops free text
// that talks about people, and compares the photos with what the listing text says.

const P7_LISTS = {
  bed_kinds: ['single', 'double', 'bunk', 'sofa_bed'],
  furniture: ['wardrobe', 'chest_of_drawers', 'nightstand', 'desk', 'chair', 'sofa', 'armchair', 'table', 'shelves'],
  appliances: ['fridge', 'oven', 'hob', 'microwave', 'washing_machine', 'dishwasher', 'tv', 'air_conditioning', 'radiator'],
  bathroom_fixtures: ['shower', 'bathtub', 'toilet', 'washbasin'],
  condition_signs: ['damp_or_mould', 'cracks_or_peeling', 'stains', 'damaged_floor', 'unfinished_works'],
};
const P7_SCALARS = ['room_type', 'beds', 'windows', 'natural_light', 'condition', 'furnished', 'readable_text', 'people_visible'];

// Words that describe a person (English, French, Arabic, Tunisian in Latin script). Free text from the model that
// contains one is not stored: the rule is to describe the room only (spec 11.2).
const PEOPLE_RE = /(?<!\p{L})(man|men|woman|women|girl|girls|boy|boys|person|persons|people|child|children|kid|kids|baby|guy|lady|ladies|gentleman|student|students|tenant|tenants|owner|homme|hommes|femme|femmes|fille|filles|gar[cç]on|gar[cç]ons|personne|personnes|enfant|enfants|b[ée]b[ée]|dame|monsieur|[ée]tudiante?s?|locataire|propri[ée]taire|rajel|mra|tfol|tofla)(?!\p{L})|رجل|امرأة|إمرأة|سيدة|بنت|ولد|طفل|شخص|أشخاص|طالب/iu;

function mentionsPeople(text) {
  return PEOPLE_RE.test(String(text || ''));
}

// Model answer (already valid against the version's schema) -> {fields, flags, dropped}.
function checkPhoto(out) {
  const fields = {};
  for (const k of P7_SCALARS) fields[k] = out[k] === undefined ? null : out[k];
  for (const [k, allowed] of Object.entries(P7_LISTS)) {
    const v = Array.isArray(out[k]) ? out[k] : [];
    fields[k] = allowed.filter((x) => v.includes(x));            // closed list, no duplicates, fixed order
  }
  const dropped = [];
  let issues = Array.isArray(out.issues) ? out.issues.map(String) : [];
  const kept = issues.filter((t) => !mentionsPeople(t));
  if (kept.length < issues.length) dropped.push('issues_about_people');
  issues = kept;
  let description = typeof out.description === 'string' ? out.description : null;
  if (description !== null && mentionsPeople(description)) { dropped.push('description_about_people'); description = null; }
  const conf = {};
  for (const [k, v] of Object.entries(out.field_confidence || {})) {
    if (k in fields && typeof v === 'number' && v >= 0 && v <= 1) conf[k] = v;
  }
  const flags = [];
  if (fields.people_visible === true) flags.push('person_in_photo');
  if (fields.readable_text === true) flags.push('text_readable_after_blur');
  if (fields.room_type === 'not_a_room') flags.push('not_a_room');
  if (fields.condition === 'poor' || fields.condition_signs.includes('damp_or_mould')) flags.push('condition_to_check');
  return { fields, issues, description, field_confidence: conf, flags, dropped };
}

// What a photo shows, in the P3 amenity vocabulary (lib/listing_check.js, P3 rule 7).
const TO_LISTING_AMENITY = { fridge: 'fridge', oven: 'oven', microwave: 'microwave', washing_machine: 'washing_machine',
  dishwasher: 'dishwasher', tv: 'tv', air_conditioning: 'air_conditioning', radiator: 'heating', desk: 'desk' };

function photoAmenities(f) {
  const seen = new Set();
  for (const x of [...(f.appliances || []), ...(f.furniture || [])]) if (TO_LISTING_AMENITY[x]) seen.add(TO_LISTING_AMENITY[x]);
  return [...seen].sort();
}

// listing: checked P3 fields {furnished, amenities}; photos: the stored analysis.vision of each photo.
// -> {issues, amenities_seen_not_in_text, analyzed, failed}. Only positive evidence is used: a photo that does not
// show a washing machine says nothing about the flat, so the absence of an object is never a contradiction.
function photoFindings(listing, photos, minConfidence = 0.5) {
  const ok = (photos || []).filter((p) => p && p.status === 'analyzed' && p.fields);
  const failed = (photos || []).filter((p) => p && p.status === 'failed').length;
  const sure = (p, k) => p.field_confidence === undefined || p.field_confidence[k] === undefined || p.field_confidence[k] >= minConfidence;
  const issues = [];
  const listed = new Set((listing && listing.amenities) || []);
  const seen = new Set();
  for (const p of ok) for (const a of photoAmenities(p.fields)) seen.add(a);
  const extra = [...seen].filter((a) => !listed.has(a)).sort();
  if (extra.length) issues.push('photos_show_amenities_not_in_text');
  const rooms = ok.filter((p) => ['bedroom', 'living_room', 'studio'].includes(p.fields.room_type));
  if (listing && listing.furnished === false && rooms.some((p) => p.fields.furnished === 'yes' && sure(p, 'furnished'))) {
    issues.push('photos_contradict_furnished');
  }
  if (listing && listing.furnished === true && rooms.length && rooms.every((p) => p.fields.furnished === 'no' && sure(p, 'furnished'))) {
    issues.push('photos_contradict_furnished');
  }
  if (ok.some((p) => (p.flags || []).includes('text_readable_after_blur'))) issues.push('photo_text_readable');
  if (ok.some((p) => (p.flags || []).includes('not_a_room'))) issues.push('photo_not_a_room');
  if (failed) issues.push('photo_analysis_failed');
  return { issues: [...new Set(issues)], amenities_seen_not_in_text: extra, analyzed: ok.length, failed };
}

if (typeof module !== 'undefined') module.exports = { P7_LISTS, P7_SCALARS, mentionsPeople, checkPhoto, photoAmenities, photoFindings };

const r = $input.first().json;
const c = $('Context').first().json;
const ctx = c.ctx || {};
const tr = $('Text analysis').first().json || {};
const tb = tr.body && typeof tr.body === 'object' ? tr.body : null;
const step = { agent: 'A1_extract', prompt_version_id: r.prompt_version_id || null, model: r.model || null,
  input: { chars: Array.from(String(c.text || '')).length, jurisdiction: c.jurisdiction_code },
  output: r.ok ? r.output : { error_code: r.error_code }, latency_ms: r.latency_ms, tokens_in: r.tokens_in || 0,
  tokens_out: r.tokens_out || 0, error: r.ok ? null : `${r.error_code}${r.detail ? ': ' + String(r.detail).slice(0, 200) : ''}` };
if (!r.ok) {
  return [{ json: { ok: false, store: false, listing_id: c.listing_id, transient: !!r.call_error,
    error: r.call_error ? 'model unavailable' : `extraction failed: ${r.error_code}`, steps: [step] } }];
}
const check = checkListing(r.output, ctx.rent_ranges || {}, ctx.default_currency || null, c.text || '');
const x = check.fields;
const issues = [...check.issues];
const exps = ctx.currencies || {};
let currency = x.rent_currency || null;
let rent_minor = toMinorUnits(x.rent_amount, x.rent_currency, exps);
if (x.rent_amount !== null && rent_minor === null) { issues.push('rent_currency_unknown'); currency = null; }
let deposit_minor = toMinorUnits(x.deposit_amount, x.deposit_currency, exps);
if (deposit_minor !== null && currency && x.deposit_currency !== currency) { issues.push('deposit_currency_differs'); deposit_minor = null; }
if (deposit_minor !== null && !currency) currency = x.deposit_currency;
if (rent_minor === null) issues.push('rent_missing');
else if (x.rent_scope === 'whole_flat' || x.rent_scope === 'unknown') issues.push(`rent_scope_${x.rent_scope}`);
// Photos against the text (P7, D-081): only what the photos show, never what they do not show.
const pf = photoFindings({ furnished: x.furnished, amenities: x.amenities || [] }, c.photos || []);
issues.push(...pf.issues);
const pii = tb && tb.pii ? tb.pii.counts || {} : null;
if (pii && ((pii.PHONE || 0) + (pii.EMAIL || 0)) > 0) issues.push('contact_details_in_text');
const fields = { kind: x.kind, rent_minor, currency: rent_minor === null && deposit_minor === null ? null : currency,
  rent_period: rent_minor === null ? null : x.rent_period, rent_scope: rent_minor === null ? null : x.rent_scope,
  deposit_minor, bills_included: x.bills_included, available_from: x.available_from, bedrooms: x.bedrooms,
  furnished: x.furnished, amenities: x.amenities || [], house_rules: x.house_rules || {}, city: x.city, neighbourhood: x.neighbourhood };
const extraction = { prompt_version_id: r.prompt_version_id, model: r.model, model_output: r.output, address_text: x.address_text,
  issues: [...new Set(issues)], model_issues: x.issues || [], field_confidence: x.field_confidence || {},
  checks_changed: check.changed, language: tb ? tb.language : null, pii_counts: pii,
  photos: { analyzed: pf.analyzed, failed: pf.failed, amenities_seen_not_in_text: pf.amenities_seen_not_in_text } };
return [{ json: { ok: true, store: true, listing_id: c.listing_id, steps: [step],
  params: [c.listing_id, JSON.stringify({ fields, description_lang: tb ? tb.language.language : null, extraction })],
  summary: { issues: extraction.issues, rent_minor, currency: fields.currency, rent_scope: fields.rent_scope } } }];

// wf.listing.extract > "Result": {ok, status, listing_id, issues, transient, error, steps}.
// status: extracted, no_text (nothing to extract), failed (model or storage); transient failures are
// retried by the analyze job (spec 5.6).
const c = $('Context').first().json;
if (!c.text || !String(c.text).trim()) {
  return [{ json: { ok: true, status: 'no_text', listing_id: c.listing_id, issues: [], transient: false, error: null, steps: [] } }];
}
const x = $('Check listing').first().json;
if (!x.ok) return [{ json: { ok: false, status: 'failed', listing_id: x.listing_id, issues: [], transient: x.transient, error: x.error, steps: x.steps } }];
const st = ($('Store extraction').first().json || {}).r || {};
if (!st.ok) {
  return [{ json: { ok: false, status: 'failed', listing_id: x.listing_id, issues: [], transient: false,
    error: `store: ${st.error_code || 'no answer'}${st.message ? ' (' + st.message + ')' : ''}`, steps: x.steps } }];
}
return [{ json: { ok: true, status: 'extracted', listing_id: x.listing_id, ...x.summary, transient: false, error: null, steps: x.steps } }];
